// Diagnostic second-time native oracle and independently closed chains.
struct SecondTimeCheck{double theta=0,zup=0,negative=0,oracleTheta=0,oracleZ[3]{};};
void NativeZupVelocity(const h::Z4cJet<AD>&u,const h::OmegaJet<AD>&o,const h::Z4cRHS<AD>&f,AD out[3]){
 auto g=h::Geometry(u.metric);AD gradf[3][3][3]{},div{},ddiv[3]{},invdot[3][3]{},connDot[3][3][3]{},gammaDot[3]{};
 for(int a=0;a<3;++a){div+=u.beta.d[a][a];for(int e=0;e<3;++e)ddiv[e]+=u.beta.dd[e][a][a];}
 for(int e=0;e<3;++e)for(int i=0;i<3;++i)for(int j=0;j<3;++j){gradf[e][i][j]=-2*(u.alpha.d[e]*u.a.k[i][j]+u.alpha.value*u.a.dk[e][i][j])-AD(2./3.)*(u.metric.dg[e][i][j]*div+u.metric.g[i][j]*ddiv[e]);for(int d=0;d<3;++d)gradf[e][i][j]+=u.beta.d[e][d]*u.metric.dg[d][i][j]+u.beta.value[d]*u.metric.ddg[e][d][i][j]+u.metric.dg[e][d][j]*u.beta.d[i][d]+u.metric.g[d][j]*u.beta.dd[e][i][d]+u.metric.dg[e][i][d]*u.beta.d[j][d]+u.metric.g[i][d]*u.beta.dd[e][j][d];}
 for(int i=0;i<3;++i)for(int j=0;j<3;++j)for(int a=0;a<3;++a)for(int b=0;b<3;++b)invdot[i][j]-=g.inverse[i][a]*f.metric[a][b]*g.inverse[b][j];
 for(int i=0;i<3;++i)for(int j=0;j<3;++j)for(int k=0;k<3;++k){for(int a=0;a<3;++a)connDot[i][j][k]+=.5*(invdot[i][a]*(u.metric.dg[j][a][k]+u.metric.dg[k][a][j]-u.metric.dg[a][j][k])+g.inverse[i][a]*(gradf[j][a][k]+gradf[k][a][j]-gradf[a][j][k]));gammaDot[i]+=invdot[j][k]*g.connection[i][j][k]+g.inverse[j][k]*connDot[i][j][k];}
 for(int i=0;i<3;++i)out[i]=o.omega*o.omega/2*(f.chi*(u.lambda.value[i]-g.contracted[i])+u.chi.value*(f.lambda[i]-gammaDot[i]));
}
SecondTimeCheck RwmSecondTime(const h::Z4cJet<AD>&u,const h::OmegaJet<AD>&o,const h::Z4cRHS<AD>&f,h::Z4cJet<AD>timed,h::OmegaJet<AD>ot,double k1,double k2,const double actualHM[4],int gaugeMode){
 SecondTimeCheck out;double av=timed.alpha.value.d[0],bv[3]={timed.beta.value[0].d[0],timed.beta.value[1].d[0],timed.beta.value[2].d[0]};h::SetStationaryOmegaNormal(timed.alpha.value,timed.beta.value,timed.alpha.d,timed.beta.d,ot);h::Z4cRHS<AD>ft{};if(!h::AssembleInterior(h::ConformalRHS(timed,ot,AD(k1),AD(k2)),ot.omega,ft))throw std::runtime_error("invalid second-time RHS");AD zv[3]{},zvt[3]{};NativeZupVelocity(u,o,f,zv);NativeZupVelocity(timed,ot,ft,zvt);
 const auto gt=h::Geometry(u.metric);auto c=h::EvolvedConstraints(u,o);AD N=u.alpha.value/o.omega,K=u.trace.value+2*u.theta.value,decay=3*o.normal+k1*(2+k2),Ci[3]{},Z[3]{},dZ[3][3]{},ginv[3][3]{},Fi[3]{},F=c.hamiltonian/2-decay*u.theta.value;
 for(int i=0;i<3;++i){Ci[i]=o.gradient[i]/o.omega+u.chi.d[i]/(2*u.chi.value);Z[i]=o.omega*o.omega*u.chi.value*(u.lambda.value[i]-gt.contracted[i])/2;for(int j=0;j<3;++j){ginv[i][j]=o.omega*o.omega*u.chi.value*gt.inverse[i][j];dZ[j][i]=(2*o.omega*o.gradient[j]*u.chi.value+o.omega*o.omega*u.chi.d[j])*(u.lambda.value[i]-gt.contracted[i])/2+o.omega*o.omega*u.chi.value*(u.lambda.d[j][i]-gt.dcontracted[j][i])/2;}}
 for(int i=0;i<3;++i){F+=dZ[i][i]-2*Ci[i]*Z[i];Fi[i]=-k1*Z[i];for(int j=0;j<3;++j)Fi[i]+=ginv[i][j]*(c.momentum[j]+u.theta.d[j]);}
 auto closed=ClosedValues(u,o,f,k1,k2,actualHM);double D0H=closed.hdot,D0M[3]={closed.mdot[0],closed.mdot[1],closed.mdot[2]},D0N=av/o.omega.v,D0decay=3*ot.normal.d[0],D0C[3]{},D0g[3][3]{};
 for(int j=0;j<3;++j){D0H-=u.beta.value[j].v*c.hamiltonian.d[j];D0N-=u.beta.value[j].v*N.d[j];D0decay-=u.beta.value[j].v*decay.d[j];for(int i=0;i<3;++i)D0M[i]-=u.beta.value[j].v*c.momentum[i].d[j];}
 for(int i=0;i<3;++i){D0C[i]=(N.d[i]*K.v+N.v*(u.trace.d[i].v+2*u.theta.d[i].v))/3;for(int j=0;j<3;++j){D0C[i]-=u.beta.dd[i][j][j].v/3;D0C[i]+=u.beta.d[i][j].v*Ci[j].v;}}
 for(int i=0;i<3;++i)for(int j=0;j<3;++j){double kraised=K.v*ginv[i][j].v/3;for(int a=0;a<3;++a)for(int b=0;b<3;++b)kraised+=o.omega.v*o.omega.v*o.omega.v*u.chi.value.v*gt.inverse[i][a].v*gt.inverse[j][b].v*u.a.k[a][b].v;D0g[i][j]=2*N.v*kraised;for(int k=0;k<3;++k)D0g[i][j]-=ginv[i][k].v*u.beta.d[k][j].v+ginv[j][k].v*u.beta.d[k][i].v;}
 double lhs=ft.theta.d[0],rhs=D0N*F.v+N.v*(D0H/2-D0decay*u.theta.value.v-decay.v*N.v*F.v),comm=0;
 for(int i=0;i<3;++i){lhs-=bv[i]*u.theta.d[i].v+2*u.beta.value[i].v*f.theta.d[i];rhs+=N.v*((N*Fi[i]).d[i]-2*D0C[i]*Z[i].v-2*Ci[i].v*N.v*Fi[i].v);for(int j=0;j<3;++j){lhs+=u.beta.value[i].v*u.beta.d[i][j].v*u.theta.d[j].v+u.beta.value[i].v*u.beta.value[j].v*u.theta.dd[i][j].v;comm+=N.v*u.beta.d[i][j].v*Z[i].d[j];}}rhs+=comm;out.oracleTheta=lhs;out.theta=std::abs(lhs-rhs)/std::max(1.,std::abs(lhs));out.negative=std::abs(comm)/std::max(1.,std::abs(lhs));
 for(int i=0;i<3;++i){double l=zvt[i].d[0],r=D0N*Fi[i].v-N.v*k1*N.v*Fi[i].v,metricPart=0;for(int j=0;j<3;++j){l-=bv[j]*Z[i].d[j]+2*u.beta.value[j].v*zv[i].d[j];r+=N.v*ginv[i][j].v*D0M[j];metricPart+=N.v*D0g[i][j]*(c.momentum[j].v+u.theta.d[j].v);r+=N.v*ginv[i][j].v*(N*F).d[j];for(int k=0;k<3;++k){l+=u.beta.value[j].v*u.beta.d[j][k].v*Z[i].d[k]+u.beta.value[j].v*u.beta.value[k].v*Z[i].dd[j][k];r+=N.v*ginv[i][j].v*u.beta.d[j][k].v*u.theta.d[k].v;}}r+=metricPart;out.oracleZ[i]=l;out.zup=std::max(out.zup,std::abs(l-r)/std::max(1.,std::abs(l)));out.negative=std::max(out.negative,std::abs(metricPart)/std::max(1.,std::abs(l)));}return out;
}
